            // always a name: a library artist spelled like a code must not be
            // searched for by code.
            discover_artist_albums(
                provider,
                db,
                &ArtistInput::name(artist.name.clone()),
                &config.discography,
                failure_cache,
            )
            .await
            .outcome
        }
    };
