fn backoff(attempt: usize) -> Duration {
    match attempt {
        0 => Duration::from_secs(1),
        _ => Duration::from_secs(2),
    }
}

/// The pause a 5xx response asked for: `Retry-After` (delta seconds) or
/// `X-RateLimit-Reset` (the epoch second the window reopens), whichever is
/// later.
///
/// Both values are advisory. A malformed or absent one yields `None` and the
/// caller falls back to its own backoff, because a 503 is an outage signal even
/// when the response says nothing useful. MusicBrainz documents that retrying
/// before the reset is very likely to fail, which is why the later of the two
/// wins over a shorter `Retry-After`.
fn server_retry_hint(response: &reqwest::Response) -> Option<Duration> {
    let retry_after = response
        .headers()
        .get("retry-after")
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.trim().parse::<u64>().ok())
        .map(Duration::from_secs);
    let until_reset = response
        .headers()
        .get("x-ratelimit-reset")
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.trim().parse::<u64>().ok())
        .map(|epoch| {
            let now = SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .map_or(epoch, |since| since.as_secs());
            Duration::from_secs(epoch.saturating_sub(now))
        });
    match (retry_after, until_reset) {
        (Some(a), Some(b)) => Some(a.max(b)),
        (hint, None) | (None, hint) => hint,
    }
}

/// Turn a 5xx response into the typed error the caller classifies and the
/// operator reads: the status, the rate-limit zone when present, the pause the
/// server asked for, and a bounded excerpt of the body.
async fn provider_error(
    mut response: reqwest::Response,
    status: u16,
    hint: Option<Duration>,
) -> DiscographyError {
    let zone = response
        .headers()
        .get("x-ratelimit-zone")
        .and_then(|value| value.to_str().ok())
        .map(str::trim)
        .filter(|zone| !zone.is_empty())
        .map(str::to_string);
    let body = match MusicBrainzProvider::read_limited(&mut response).await {
        Ok(bytes) => {
            let text = String::from_utf8_lossy(&bytes)
                .split_whitespace()
                .collect::<Vec<_>>()
                .join(" ");
            if text.chars().count() > MAX_ERROR_BODY_CHARS {
                let kept: String = text.chars().take(MAX_ERROR_BODY_CHARS).collect();
                format!("{kept}...")
            } else {
                text
            }
        }
        Err(_) => "<body omitted>".to_string(),
    };
    let mut parts = Vec::new();
    if let Some(zone) = zone {
        parts.push(format!("rate-limit zone {zone}"));
    }
    if let Some(wait) = hint {
        parts.push(format!("retry after {}s", wait.as_secs()));
        if wait > Duration::from_secs(MAX_RETRY_AFTER) {
            parts.push(format!(
                "not retried: the hint exceeds the {MAX_RETRY_AFTER}s retry cap"
            ));
        }
    }
    if !body.is_empty() {
        parts.push(format!("body: {body}"));
    }
    let detail = if parts.is_empty() {
        String::new()
    } else {
        format!(" ({})", parts.join("; "))
    };
    DiscographyError::ProviderError { status, detail }
}

